#include <iostream>
#include <string>
#include <stdexcept>
#include <iomanip>

class CommissionEmployee {
public:
    CommissionEmployee(const std::string& first, const std::string& last,
                       const std::string& ssn, double sales, double rate)
        : firstName(first), lastName(last), socialSecurityNumber(ssn) {
        setGrossSales(sales);
        setCommissionRate(rate);
    }

    void setGrossSales(double sales) {
        if (sales < 0.0) {
            throw std::invalid_argument("Gross sales must be >= 0.0");
        }
        grossSales = sales;
    }
    double getGrossSales() const { return grossSales; }

    void setCommissionRate(double rate) {
        if (rate <= 0.0 || rate >= 1.0) {
            throw std::invalid_argument("Commission rate must be > 0.0 and < 1.0");
        }
        commissionRate = rate;
    }
    double getCommissionRate() const { return commissionRate; }

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    double earnings() const {
        return getCommissionRate() * getGrossSales();
    }

    void print() const {
        std::cout << "commission employee: " << firstName << ' ' << lastName
                  << "\nsocial security number: " << socialSecurityNumber
                  << "\ngross sales: " << grossSales
                  << "\ncommission rate: " << commissionRate;
    }

private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales{0.0};
    double commissionRate{0.0};
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(const std::string& first, const std::string& last,
                               const std::string& ssn, double sales, double rate, double salary)
        : CommissionEmployee(first, last, ssn, sales, rate) {
        setBaseSalary(salary);
    }

    void setBaseSalary(double salary) {
        if (salary < 0.0) {
            throw std::invalid_argument("Salary must be >= 0.0");
        }
        baseSalary = salary;
    }
    double getBaseSalary() const { return baseSalary; }

    // Tái định nghĩa earnings() và gọi hàm của lớp cha tường minh
    double earnings() const {
        return getBaseSalary() + CommissionEmployee::earnings();
    }

    // Tái định nghĩa print() và gọi hàm của lớp cha tường minh
    void print() const {
        std::cout << "base-salaried ";
        CommissionEmployee::print();
        std::cout << "\nbase salary: " << getBaseSalary() << "\n";
    }

private:
    double baseSalary{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);
    BasePlusCommissionEmployee emp("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);
    emp.print();
    std::cout << "total earnings: " << emp.earnings() << "\n";
    return 0;
}

#include <iostream>

class Base {
public:
    Base(int val) : baseValue(val) {
        std::cout << "1. Base constructor body executed (value: " << baseValue << ")\n";
    }
private:
    int baseValue;
};

class Derived : public Base {
public:
    Derived(int bVal, int dVal)
        : Base(bVal), derivedValue(dVal) { // Lớp cơ sở được gọi trước trong danh sách khởi tạo
        std::cout << "2. Derived constructor body executed (value: " << derivedValue << ")\n";
    }
private:
    int derivedValue;
};

int main() {
    std::cout << "Creating Derived object:\n";
    Derived obj(10, 20);
    return 0;
}
